package de.teamlapen.vampirism.common.world.blockentity;

import de.teamlapen.faction.common.world.blockentity.NetworkedBlockEntity;
import de.teamlapen.vampirism.common.core.ModBlockEntities;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.util.ProblemReporter;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.ambient.Bat;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.TagValueOutput;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import org.jetbrains.annotations.Nullable;

import java.util.stream.Stream;

public class BatCageBlockEntity extends NetworkedBlockEntity {

    public static final String KEY_ENTITY_INSIDE = "EntityInside";

    private @Nullable CompoundTag entityTag;

    public BatCageBlockEntity(BlockPos pos, BlockState blockState) {
        super(ModBlockEntities.BAT_CAGE.get(), pos, blockState);
    }

    @Override
    protected void loadAdditional(ValueInput input) {
        super.loadAdditional(input);
        this.entityTag = input.read(KEY_ENTITY_INSIDE, CompoundTag.CODEC).orElse(null);
    }

    @Override
    protected void saveAdditional(ValueOutput output) {
        super.saveAdditional(output);
        if (this.entityTag != null) {
            output.store(KEY_ENTITY_INSIDE, CompoundTag.CODEC, this.entityTag);
        }
    }

    public void setEntity(Entity entity) {
        if (this.level != null && this.level.isClientSide()) return;

        this.entityTag = serializeEntity(entity);
        if (this.entityTag != null) {
            this.entityTag = sanitizeEntityTag(this.entityTag);
        }

        entity.remove(Entity.RemovalReason.DISCARDED);
        setChanged();
    }

    public static @Nullable CompoundTag serializeEntity(Entity entity) {
        if (entity.isRemoved() || entity.level().isClientSide()) {
            return null;
        }

        TagValueOutput output = TagValueOutput.createWithoutContext(ProblemReporter.DISCARDING);

        if (entity.save(output)) {
            return output.buildResult();
        }

        return null;
    }

    public static CompoundTag sanitizeEntityTag(CompoundTag tag) {
        tag = tag.copy();
        Stream.of(
                "UUID",
                "Pos",
                "Motion",
                "Rotation",
                "FallDistance",
                "Fire",
                "Air",
                "OnGround",
                "Dimension",
                "PortalCooldown",
                "Leash"
        ).forEach(tag::remove);

        return tag;
    }

    public void setEntityTag(@Nullable CompoundTag entityTag) {
        if (this.level != null && this.level.isClientSide()) return;

        this.entityTag = entityTag;
        setChanged();
    }

    public boolean hasEntity() {
        return this.entityTag != null;
    }

    public @Nullable CompoundTag getEntityTag() {
        return entityTag;
    }

    public static boolean canContainEntity(Entity entity) {
        return entity instanceof Bat;
    }
}

package de.teamlapen.vampirism.common.world.blockentity;

import de.teamlapen.faction.common.world.blockentity.NetworkedBlockEntity;
import de.teamlapen.vampirism.common.core.ModBlockEntities;
import de.teamlapen.vampirism.common.core.ModFluids;
import de.teamlapen.vampirism.common.util.BloodHelper;
import de.teamlapen.vampirism.common.world.fluids.ControllableFluidTank;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.fluids.FluidStack;
import net.neoforged.neoforge.fluids.FluidType;
import net.neoforged.neoforge.transfer.fluid.FluidResource;
import net.neoforged.neoforge.transfer.transaction.Transaction;

public class BloodContainerBlockEntity extends NetworkedBlockEntity {

    public static final int CAPACITY = FluidType.BUCKET_VOLUME * 5;

    public final ControllableFluidTank fluidInventory;

    public BloodContainerBlockEntity(BlockPos pos, BlockState blockState) {
        super(ModBlockEntities.BLOOD_CONTAINER.get(), pos, blockState);
        this.fluidInventory = new ControllableFluidTank(CAPACITY, this::setChanged, fluid -> fluid.is(ModFluids.BLOOD) || BloodHelper.isConvertibleToBlood(fluid), true, true);
    }

    @Override
    protected void loadAdditional(ValueInput input) {
        super.loadAdditional(input);
        this.fluidInventory.deserialize(input);
    }

    @Override
    protected void saveAdditional(ValueOutput output) {
        super.saveAdditional(output);
        this.fluidInventory.serialize(output);
    }

    public FluidStack getFluid() {
        FluidResource resource = this.fluidInventory.getResource();
        return resource.toStack(this.fluidInventory.getAmount());
    }

    public void setFluid(FluidStack fluid) {
        try (var transaction = Transaction.openRoot()) {
            FluidResource resource = this.fluidInventory.getResource();
            if (!resource.isEmpty()) {
                int amount = this.fluidInventory.getAmount();
                this.fluidInventory.extract(resource, amount, transaction);
            }
            if (!fluid.isEmpty()) {
                this.fluidInventory.insert(FluidResource.of(fluid), fluidInventory.getAmount(), transaction);
            }
            transaction.commit();
        }
    }
}

package de.teamlapen.vampirism.common.world.blockentity;

import de.teamlapen.faction.common.world.blockentity.NetworkedBlockEntity;
import de.teamlapen.vampirism.common.core.ModBlockEntities;
import de.teamlapen.vampirism.common.core.ModSounds;
import de.teamlapen.vampirism.common.world.blocks.CoffinBlock;
import net.minecraft.core.BlockPos;
import net.minecraft.sounds.SoundSource;
import net.minecraft.util.Mth;
import net.minecraft.world.item.DyeColor;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;

/**
 * TileEntity for coffins. Handles coffin lid position and color
 */
public class CoffinBlockEntity extends NetworkedBlockEntity {
    public float lidPos;
    public DyeColor color = DyeColor.RED;
    private boolean playLidSoundFlag;

    public CoffinBlockEntity(BlockPos pos, BlockState state) {
        super(ModBlockEntities.COFFIN.get(), pos, state);
    }

    public CoffinBlockEntity(BlockPos pos, BlockState state, DyeColor color) {
        super(ModBlockEntities.COFFIN.get(), pos, state);
        this.color = color;
    }

    public void changeColor(DyeColor color) {
        this.color = color;
        setChanged();
    }

    @Override
    public void loadAdditional(ValueInput input) {
        super.loadAdditional(input);
        this.color = input.read("color", DyeColor.CODEC).orElse(DyeColor.BLACK);
        this.lidPos = input.getFloatOr("lidPos", 0);
        this.playLidSoundFlag = this.lidPos==0;
    }

    @Override
    public void saveAdditional(ValueOutput output) {
        super.saveAdditional(output);
        output.store("color", DyeColor.CODEC, this.color);
        output.putFloat("lidPos", this.lidPos);
    }

    public static void clientTickHead(Level level, BlockPos pos, BlockState state, CoffinBlockEntity blockEntity) {
        boolean occupied = CoffinBlock.isClosed(level, pos);
        if (blockEntity.playLidSoundFlag != occupied) {
            level.playLocalSound(pos.getX(), (double) pos.getY() + 0.5D, pos.getZ(), ModSounds.COFFIN_LID.get(), SoundSource.BLOCKS, 0.5F, level.getRandom().nextFloat() * 0.1F + 0.9F, true);
            blockEntity.playLidSoundFlag = CoffinBlock.isClosed(level, pos);
        }

        // Calculate lid position
        boolean isClosed = blockEntity.hasLevel() && CoffinBlock.isClosed(level, pos);
        if (!isClosed) {
            blockEntity.lidPos += 0.02F;
        } else {
            blockEntity.lidPos -= 0.02F;
        }
        blockEntity.lidPos = Mth.clamp(blockEntity.lidPos, 0, 1);

    }
}

package de.teamlapen.vampirism.common.world.blocks;

import com.mojang.serialization.MapCodec;
import de.teamlapen.vampirism.common.core.ModBlocks;
import de.teamlapen.vampirism.common.core.ModDataComponents;
import de.teamlapen.vampirism.common.world.blockentity.BatCageBlockEntity;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.stats.Stats;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.LevelReader;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.StateDefinition;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.block.state.properties.BooleanProperty;
import net.minecraft.world.level.block.state.properties.EnumProperty;
import net.minecraft.world.phys.shapes.BooleanOp;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;
import org.jetbrains.annotations.Nullable;

import java.util.Optional;

public class BatCageBlock extends BaseEntityBlock {

    public static final MapCodec<BatCageBlock> CODEC = simpleCodec(BatCageBlock::new);

    public static final EnumProperty<Direction> FACING = BlockStateProperties.HORIZONTAL_FACING;
    public static final BooleanProperty CONTAINS_BAT = BooleanProperty.create("contains_bat");

    private static final VoxelShape SHAPE = Shapes.join(Block.box(1, 0, 1, 15, 12, 15), Block.box(3, 12, 3, 13, 16, 13), BooleanOp.OR);

    public BatCageBlock(Properties properties) {
        super(properties);
        this.registerDefaultState(this.defaultBlockState().setValue(FACING, Direction.NORTH).setValue(CONTAINS_BAT, false));
    }

    public static ItemStack createBatCageStack(@Nullable BlockEntity blockEntity) {
        CompoundTag entityTag = null;
        if (blockEntity instanceof BatCageBlockEntity batCageBlockEntity) {
            entityTag = batCageBlockEntity.getEntityTag();
        }
        return createBatCageStack(entityTag);
    }

    public static ItemStack createBatCageStack(@Nullable CompoundTag entityTag) {
        ItemStack stack = new ItemStack(ModBlocks.BAT_CAGE.get());
        if (entityTag != null) {
            stack.set(ModDataComponents.HELD_ENTITY, entityTag);
        }
        return stack;
    }

    @Override
    protected MapCodec<? extends BaseEntityBlock> codec() {
        return CODEC;
    }

    @Nullable
    @Override
    public BlockEntity newBlockEntity(BlockPos pPos, BlockState pState) {
        return new BatCageBlockEntity(pPos, pState);
    }

    @Override
    public void playerDestroy(Level level, Player player, BlockPos pos, BlockState state, @Nullable BlockEntity blockEntity, ItemStack tool) {
        player.awardStat(Stats.BLOCK_MINED.get(this));
        player.causeFoodExhaustion(0.005F);
        popResource(level, pos, createBatCageStack(blockEntity));
    }

    @Override
    public void setPlacedBy(Level level, BlockPos pos, BlockState state, @Nullable LivingEntity placer, ItemStack stack) {
        super.setPlacedBy(level, pos, state, placer, stack);
        if (!stack.isEmpty()) {
            getBlockEntity(level, pos).ifPresent(blockEntity -> {
                CompoundTag tag = stack.get(ModDataComponents.HELD_ENTITY.get());
                if (tag != null) {
                    blockEntity.setEntityTag(tag.copy());
                    blockEntity.setChanged();
                }
            });
        }
    }

    @Override
    public ItemStack getCloneItemStack(LevelReader level, BlockPos pos, BlockState state, boolean includeData, Player player) {
        return createBatCageStack(getBlockEntity(level, pos).orElse(null));
    }

    @Override
    public VoxelShape getShape(BlockState pState, BlockGetter pLevel, BlockPos pPos, CollisionContext pContext) {
        return SHAPE;
    }

    @Override
    public RenderShape getRenderShape(BlockState pState) {
        return RenderShape.MODEL;
    }

    @Override
    protected void createBlockStateDefinition(StateDefinition.Builder<Block, BlockState> builder) {
        builder.add(FACING, CONTAINS_BAT);
    }

    @Override
    public BlockState mirror(BlockState pState, Mirror pMirror) {
        return pState.setValue(FACING, pMirror.mirror(pState.getValue(FACING)));
    }

    @Override
    public BlockState rotate(BlockState pState, Rotation pRot) {
        return pState.setValue(FACING, pRot.rotate(pState.getValue(FACING)));
    }

    @Nullable
    @Override
    public BlockState getStateForPlacement(BlockPlaceContext context) {
        return this.defaultBlockState().setValue(FACING, context.getHorizontalDirection()).setValue(CONTAINS_BAT, context.getItemInHand().has(ModDataComponents.HELD_ENTITY));
    }

    @Override
    protected boolean hasAnalogOutputSignal(BlockState state) {
        return true;
    }

    @Override
    protected int getAnalogOutputSignal(BlockState state, Level level, BlockPos pos, Direction direction) {
        return getBlockEntity(level, pos).map(blockEntity -> blockEntity.hasEntity() ? 15 : 0).orElse(0);
    }

    public Optional<BatCageBlockEntity> getBlockEntity(LevelReader level, BlockPos pos) {
        if (level.getBlockEntity(pos) instanceof BatCageBlockEntity blockEntity) {
            return Optional.of(blockEntity);
        }

        return Optional.empty();
    }
}

package de.teamlapen.vampirism.common.world.entity;

import de.teamlapen.vampirism.common.core.ModEntities;
import de.teamlapen.vampirism.common.core.ModItems;
import de.teamlapen.vampirism.common.util.Helper;
import net.minecraft.core.BlockPos;
import net.minecraft.network.syncher.EntityDataAccessor;
import net.minecraft.network.syncher.EntityDataSerializers;
import net.minecraft.network.syncher.SynchedEntityData;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.tags.FluidTags;
import net.minecraft.util.Mth;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntitySelector;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.MoverType;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.entity.projectile.ItemSupplier;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.minecraft.world.phys.Vec3;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

/**
 * Similar to EntityXPOrb
 */
public class SoulOrbEntity extends Entity implements ItemSupplier {

    public static final EntityDataAccessor<String> TYPE_PARAMETER = SynchedEntityData.defineId(SoulOrbEntity.class, EntityDataSerializers.STRING);
    private int delayBeforePickup;
    private @Nullable Player player;
    private int age;
    @Nullable
    private ItemStack soulItemStack;

    public SoulOrbEntity(@NotNull Level worldIn, double x, double y, double z, @NotNull VARIANT type) {
        super(ModEntities.SOUL_ORB.get(), worldIn);
        this.setVariant(type);
        delayBeforePickup = 10;
        this.setPos(x, y, z);
        this.setYRot((float) (Math.random() * 360.0D));
        this.setDeltaMovement((this.random.nextDouble() * (double) 0.2F - (double) 0.1F) * 2.0D, this.random.nextDouble() * 0.2D * 2.0D, (this.random.nextDouble() * (double) 0.2F - (double) 0.1F) * 2.0D);
    }

    public SoulOrbEntity(@NotNull EntityType<? extends SoulOrbEntity> type, @NotNull Level worldIn) {
        super(type, worldIn);
    }


    public @NotNull VARIANT getVariant() {
        return VARIANT.valueOf(getEntityData().get(TYPE_PARAMETER));
    }

    private void setVariant(@NotNull VARIANT type) {
        getEntityData().set(TYPE_PARAMETER, type.name());
    }


    @NotNull
    @Override
    public ItemStack getItem() {
        return getSoulItemStack();
    }

    @NotNull
    public ItemStack getSoulItemStack() {
        if (soulItemStack == null) {
            soulItemStack = createSoulItemStack();
        }
        return soulItemStack;
    }

    @Override
    public boolean hurtServer(@NotNull ServerLevel level, @NotNull DamageSource source, float amount) {
        return false;
    }

    @Override
    public boolean isAttackable() {
        return false;
    }

    @Override
    public boolean isInvisibleTo(@NotNull Player player) {
        if (getVariant() == VARIANT.VAMPIRE) {
            return !Helper.isHunter(player) || player.isSpectator();
        }
        return true;
    }

    @Override
    public void playerTouch(@NotNull Player entityIn) {
        if (!this.level().isClientSide()) {
            if (delayBeforePickup == 0) {
                if (Helper.isHunter(entityIn)) {
                    if (entityIn.getInventory().add(getSoulItemStack())) {
                        entityIn.take(this, 1);
                        this.discard();
                    }
                }
            }
        }
    }

    @Override
    public void tick() {
        super.tick();
        if (delayBeforePickup > 0) {
            delayBeforePickup--;
        }

        this.xo = this.getX();
        this.yo = this.getY();
        this.zo = this.getZ();

        if (this.isEyeInFluid(FluidTags.WATER)) {
            Vec3 vec3d = this.getDeltaMovement();
            this.setDeltaMovement(vec3d.x * (double) 0.99F, Math.min(vec3d.y + (double) 5.0E-4F, 0.06F), vec3d.z * (double) 0.99F);
        } else if (!this.isNoGravity()) {
            this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.03D, 0.0D));
        }

        if (this.level().getFluidState(blockPosition()).is(FluidTags.LAVA)) {
            this.setDeltaMovement((this.random.nextFloat() - this.random.nextFloat()) * 0.2F, 0.2F, (this.random.nextFloat() - this.random.nextFloat()) * 0.2F);
            this.playSound(SoundEvents.GENERIC_BURN, 0.4F, 2.0F + this.random.nextFloat() * 0.4F);
        }
        if (!this.level().noCollision(this.getBoundingBox())) { //areCollisionShapesEmpty
            this.moveTowardsClosestSpace(this.getX(), (this.getBoundingBox().minY + this.getBoundingBox().maxY) / 2.0D, this.getZ());
        }


        if (this.age % 10 == 5 & (this.player == null || !this.player.isAlive() || this.player.distanceToSqr(this) > 64)) {
            this.player = this.level().getNearestPlayer(this.getX(), this.getY(), this.getZ(), 8, EntitySelector.NO_SPECTATORS.and(Helper::isHunter));
        }

        if (this.player != null) {
            Vec3 vec3d = new Vec3(this.player.getX() - this.getX(), this.player.getY() + (double) this.player.getEyeHeight() / 2.0D - this.getY(), this.player.getZ() - this.getZ());
            double d1 = vec3d.lengthSqr();
            if (d1 < 64.0D) {
                double d2 = 1.0D - Math.sqrt(d1) / 8.0D;
                this.setDeltaMovement(this.getDeltaMovement().add(vec3d.normalize().scale(d2 * d2 * 0.1D)));
            }
        }

        this.move(MoverType.SELF, this.getDeltaMovement());
        float f = 0.98F;

        if (this.onGround()) {
            BlockPos underPos = new BlockPos(Mth.floor(this.getX()), Mth.floor(this.getBoundingBox().minY) - 1, Mth.floor(this.getZ()));
            BlockState underState = this.level().getBlockState(underPos);
            f = underState.getBlock().getFriction(underState, this.level(), underPos, this) * 0.98F;
        }

        this.setDeltaMovement(this.getDeltaMovement().multiply(f, 0.9800000190734863D, f));

        if (this.onGround()) {
            this.setDeltaMovement(this.getDeltaMovement().multiply(1D, -0.8999999761581421D, 1D));
        }


        this.age++;

        if (this.age >= 6000) {
            this.discard();
        }
    }

    @Override
    protected void addAdditionalSaveData(@NotNull ValueOutput output) {
        output.putString("type", this.getVariant().name());
        output.putInt("age", age);
    }

    @Override
    protected void defineSynchedData(SynchedEntityData.Builder builder) {
        builder.define(TYPE_PARAMETER, VARIANT.NONE.name());
    }

    @NotNull
    @Override
    protected MovementEmission getMovementEmission() {
        return MovementEmission.NONE;
    }


    @Override
    protected void readAdditionalSaveData(@NotNull ValueInput input) {
        this.setVariant(input.getString("type").map(VARIANT::valueOf).orElse(VARIANT.NONE));
        this.age = input.getIntOr("age", 0);
        this.soulItemStack = null;//Reset item just in case an item of a different type has been created beforehand
    }

    private @NotNull ItemStack createSoulItemStack() {
        //noinspection IfStatementWithIdenticalBranches
        if (getVariant() == VARIANT.VAMPIRE) {
            return new ItemStack(ModItems.SOUL_ORB_VAMPIRE.get());
        }
        return new ItemStack(ModItems.SOUL_ORB_VAMPIRE.get());
    }


    public enum VARIANT {
        NONE, VAMPIRE
    }
}

package de.teamlapen.vampirism.common.world.entity;

import de.teamlapen.vampirism.common.core.ModEntities;
import de.teamlapen.vampirism.common.core.ModItems;
import net.minecraft.network.syncher.EntityDataAccessor;
import net.minecraft.network.syncher.EntityDataSerializers;
import net.minecraft.network.syncher.SynchedEntityData;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.projectile.throwableitemprojectile.ThrowableItemProjectile;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.minecraft.world.phys.HitResult;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import org.jetbrains.annotations.NotNull;

public class ThrowableItemEntity extends ThrowableItemProjectile {

    private final static Logger LOGGER = LogManager.getLogger(ThrowableItemEntity.class);

    public ThrowableItemEntity(@NotNull EntityType<? extends ThrowableItemEntity> type, @NotNull Level worldIn) {
        super(type, worldIn);
    }

    public ThrowableItemEntity(@NotNull ServerLevel level, @NotNull LivingEntity thrower, ItemStack source) {
        super(ModEntities.THROWABLE_ITEM.get(), thrower, level, source);
        this.setOwner(thrower);
    }

    public ThrowableItemEntity(@NotNull Level worldIn, double pX, double pY, double pZ, ItemStack source) {
        super(ModEntities.THROWABLE_ITEM.get(), pX, pY, pZ, worldIn, source);
    }

    @Override
    protected @NotNull Item getDefaultItem() {
        return ModItems.HOLY_WATER_BOTTLE_NORMAL.get();
    }

    @Override
    public void addAdditionalSaveData(@NotNull ValueOutput output) {
        super.addAdditionalSaveData(output);
        ItemStack stack = getItem();
        if (!stack.isEmpty()) {
            output.store("thrownItem", ItemStack.CODEC, stack);
        }
    }

    @Override
    public void readAdditionalSaveData(@NotNull ValueInput input) {
        super.readAdditionalSaveData(input);
        input.read("thrownItem", ItemStack.CODEC).ifPresentOrElse(this::setItem, this::discard);
    }

    @Override
    protected double getDefaultGravity() {
        return 0.05;
    }

    @Override
    protected void onHit(@NotNull HitResult result) {
        ItemStack stack = getItem();
        if (!stack.isEmpty()) {
            Item item = stack.getItem();
            if (item instanceof IVampirismThrowableItem) {
                ((IVampirismThrowableItem) item).onImpact(this, stack, result, this.level().isClientSide());
            } else {
                LOGGER.warn("Saved item ({}) is not an instance of IVampirismThrowableItem. This should not be able to happen", stack);
            }
        }
        if (!this.level().isClientSide()) this.discard();
    }

    /**
     * Has to be implemented by any item, that can be thrown using {@link ThrowableItemEntity}
     */
    public interface IVampirismThrowableItem {
        /**
         * Is called when the throwable entity impacts.
         * Entity is set to dead afterwards
         *
         * @param entity The throwable entity
         * @param stack  The stack this entity is representing
         * @param impact The impact raytrace
         * @param remote If this is a remote world
         */
        void onImpact(ThrowableItemEntity entity, ItemStack stack, HitResult impact, boolean remote);
    }
}

package de.teamlapen.vampirism.common.world.items;

import de.teamlapen.vampirism.common.core.ModDataComponents;
import de.teamlapen.vampirism.common.world.blockentity.BatCageBlockEntity;
